import React, { useState, useEffect } from "react";
import "./JumbleGame.css";

const JumbleGame = ({
  question,
  onAnswerSubmit,
  timer,
  answerSubmitted,
  showFeedback,
  isCorrectAnswer,
}) => {
  const [userAnswer, setUserAnswer] = useState("");

  useEffect(() => {
    if (!answerSubmitted) {
      setUserAnswer("");
    }
  }, [question, answerSubmitted]);

  // Auto-submit validation when timer runs out and answer hasn't been submitted
  useEffect(() => {
    if (timer === 0 && !answerSubmitted && userAnswer.trim()) {
      // Auto-validate the answer when time runs out
      onAnswerSubmit(userAnswer);
    }
  }, [timer, answerSubmitted, userAnswer, onAnswerSubmit]);

  return (
    <div className="jumble-question">
      <h2>Unscramble the Word</h2>
      <div className="jumbled-word">{question.jumbled}</div>
      <input
        type="text"
        value={userAnswer}
        onChange={(e) => setUserAnswer(e.target.value)}
        placeholder="Enter the correct word"
        className="answer-input"
        disabled={answerSubmitted}
      />

      {!answerSubmitted ? (
        <button
          className="submit-btn"
          onClick={() => onAnswerSubmit(userAnswer)}
          disabled={!userAnswer.trim()}
        >
          Submit Answer
        </button>
      ) : (
        showFeedback && (
          <div
            className={`feedback ${isCorrectAnswer ? "correct" : "incorrect"}`}
          >
            {isCorrectAnswer ? (
              "Correct! Well done!"
            ) : (
              <div>
                <p>Incorrect answer.</p>
                <p>
                  The correct word is: <strong>{question.answer}</strong>
                </p>
              </div>
            )}
          </div>
        )
      )}

      {/* Show correct answer when time runs out and no answer was submitted */}
      {timer === 0 && !answerSubmitted && !userAnswer.trim() && (
        <div className="feedback incorrect">
          <p>Time's up! No answer submitted.</p>
          <p>
            The correct word is: <strong>{question.answer}</strong>
          </p>
        </div>
      )}
    </div>
  );
};

export default JumbleGame;
